Your expense tracker is below. Pick a month, set a budget, add expenses, and it totals them by category. It tries to save on this device, but that may not work inside chat, so don't rely on it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:12px;color:#222;background:#fff;font-size:14px}
h3{margin:0 0 10px}
.row{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;align-items:center}
input,select,button{padding:6px 8px;font-size:14px;border:1px solid #bbb;border-radius:6px}
button{background:#2f7d5b;color:#fff;border-color:#2f7d5b;cursor:pointer}
button.x{background:#fff;color:#b00;border-color:#ddd;padding:2px 8px}
.cards{display:flex;gap:8px;margin-bottom:10px}
.card{flex:1;border:1px solid #ddd;border-radius:8px;padding:8px}
.card b{display:block;font-size:18px}
.bar{height:8px;background:#e6efe9;border-radius:4px;overflow:hidden}
.bar i{display:block;height:100%;background:#2f7d5b}
.cat{display:grid;grid-template-columns:80px 1fr 90px;gap:8px;align-items:center;margin:4px 0}
.cat span:last-child{text-align:right}
table{width:100%;border-collapse:collapse;margin-top:8px}
td{padding:5px 4px;border-bottom:1px solid #eee}
td.r{text-align:right}
.over{color:#b00}
.muted{color:#777}
</style></head><body>
<h3>Monthly expenses</h3>
<div class="row">
  <label>Month <input type="month" id="m"></label>
  <label>Budget ₹ <input type="number" id="b" min="0" style="width:110px"></label>
</div>
<div class="cards">
  <div class="card">Spent<b id="tot">₹0</b></div>
  <div class="card">Left<b id="left">-</b></div>
</div>
<div class="bar" style="height:10px;margin-bottom:12px"><i id="pbar" style="width:0"></i></div>
<div class="row">
  <input type="date" id="d">
  <select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Fun</option><option>Other</option></select>
  <input id="n" placeholder="Note" style="flex:1;min-width:90px">
  <input type="number" id="a" placeholder="Amount ₹" min="0" style="width:100px">
  <button id="add" type="button">Add</button>
</div>
<div id="cats"></div>
<table><tbody id="rows"></tbody></table>
<p class="muted" id="empty"></p>
<script>
var $=function(i){return document.getElementById(i)};
var items=[],budget=0;
function fmt(n){return '₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2})}
function save(){try{
  localStorage.setItem('exp',items.map(function(x){return [x.d,x.c,x.n.replace(/[|\n]/g,' '),x.a].join('|')}).join('\n'));
  localStorage.setItem('bud',String(budget));
}catch(e){}}
function load(){try{
  var s=localStorage.getItem('exp');
  if(s){items=s.split('\n').map(function(l){var p=l.split('|');return{d:p[0],c:p[1],n:p[2]||'',a:+p[3]}})}
  budget=+localStorage.getItem('bud')||0;
}catch(e){}}
function cell(tr,txt,cls){var td=document.createElement('td');td.textContent=txt;if(cls)td.className=cls;tr.appendChild(td);return td}
function render(){
  var mo=$('m').value;
  var list=items.filter(function(x){return x.d.slice(0,7)===mo}).sort(function(a,b){return a.d<b.d?1:-1});
  var total=0,by={};
  list.forEach(function(x){total+=x.a;by[x.c]=(by[x.c]||0)+x.a});
  $('tot').textContent=fmt(total);
  var L=$('left');
  if(budget>0){
    var diff=budget-total;
    L.textContent=diff>=0?fmt(diff):'Over by '+fmt(-diff);
    L.className=diff<0?'over':'';
    $('pbar').style.width=Math.min(100,total/budget*100)+'%';
  }else{L.textContent='-';L.className='';$('pbar').style.width='0'}
  var cd=$('cats');cd.textContent='';
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    var r=document.createElement('div');r.className='cat';
    var a=document.createElement('span');a.textContent=k;
    var bw=document.createElement('div');bw.className='bar';
    var bi=document.createElement('i');bi.style.width=(by[k]/total*100)+'%';bw.appendChild(bi);
    var v=document.createElement('span');v.textContent=fmt(by[k]);
    r.appendChild(a);r.appendChild(bw);r.appendChild(v);cd.appendChild(r);
  });
  var tb=$('rows');tb.textContent='';
  list.forEach(function(x){
    var tr=document.createElement('tr');
    cell(tr,x.d.slice(8)+'/'+x.d.slice(5,7));
    cell(tr,x.c);
    cell(tr,x.n,'muted');
    cell(tr,fmt(x.a),'r');
    var td=document.createElement('td');
    var bt=document.createElement('button');bt.type='button';bt.className='x';bt.textContent='✕';
    bt.onclick=function(){items.splice(items.indexOf(x),1);save();render()};
    td.appendChild(bt);tr.appendChild(td);tb.appendChild(tr);
  });
  $('empty').textContent=list.length?'':'No expenses in this month yet.';
}
$('add').onclick=function(){
  var d=$('d').value,a=parseFloat($('a').value);
  if(!d||!(a>0))return;
  items.push({d:d,c:$('c').value,n:$('n').value,a:a});
  $('m').value=d.slice(0,7);
  $('n').value='';$('a').value='';
  save();render();
};
$('b').oninput=function(){budget=parseFloat($('b').value)||0;save();render()};
$('m').onchange=render;
var today=new Date().toISOString().slice(0,10);
load();
$('d').value=today;$('m').value=today.slice(0,7);
if(budget)$('b').value=budget;
render();
</script></body></html>
```
